INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-17', 'es', 'LAIKA 64 3.0', 'Ajustes rediseñados con colores, animaciones y la pestaña Novedades. Perfiles con estadísticas y portadas, 133 avatares, emojis y 32 frases rápidas. La conexión directa aguanta los microcortes. Música del juego, imágenes tras el video y Reportar un juego con GitHub.'),
 ('2026-11-17', 'en', 'LAIKA 64 3.0', 'Redesigned Settings with colours, animations and a What''s new tab. Profiles with stats and covers, 133 avatars, emojis and 32 quick phrases. The direct connection rides out short drops. Game music, pictures after the video and Report a game with GitHub.'),
 ('2026-11-17', 'pt', 'LAIKA 64 3.0', 'Ajustes redesenhados com cores, animações e a aba Novidades. Perfis com estatísticas e capas, 133 avatares, emojis e 32 frases rápidas. A conexão direta aguenta quedas curtas. Música do jogo, imagens após o vídeo e Reportar um jogo com o GitHub.'),
 ('2026-11-17', 'fr', 'LAIKA 64 3.0', 'Réglages repensés avec couleurs, animations et onglet Nouveautés. Profils avec statistiques et jaquettes, 133 avatars, emojis et 32 phrases rapides. La connexion directe supporte les micro-coupures. Musique du jeu, images après la vidéo et Signaler un jeu avec GitHub.'),
 ('2026-11-17', 'it', 'LAIKA 64 3.0', 'Impostazioni ridisegnate con colori, animazioni e la scheda Novità. Profili con statistiche e copertine, 133 avatar, emoji e 32 frasi rapide. La connessione diretta regge i brevi cali. Musica del gioco, immagini dopo il video e Segnala un gioco con GitHub.'),
 ('2026-11-17', 'de', 'LAIKA 64 3.0', 'Neue Einstellungen mit Farben, Animationen und Neuigkeiten-Tab. Profile mit Statistik und Covern, 133 Avatare, Emojis und 32 Schnellsätze. Die Direktverbindung übersteht kurze Aussetzer. Spielmusik, Bilder nach dem Video und Spiel melden mit GitHub.'),
 ('2026-11-17', 'ru', 'LAIKA 64 3.0', 'Новые настройки с цветами, анимацией и вкладкой Новое. Профили со статистикой и обложками, 133 аватара, эмодзи и 32 быстрые фразы. Прямое соединение переживает короткие обрывы. Музыка игры, картинки после видео и Сообщить об игре через GitHub.');
